(()=>{'use strict';
const api=()=>window.CAGE_BACKEND,$=id=>document.getElementById(id);let prefs={push_enabled:false,quiet_start:null,quiet_end:null,timezone:'Africa/Blantyre'},pushEnabled=false;
window.CAGE_PUSH={get enabled(){return pushEnabled;}};
const button=document.createElement('button');button.id='experience-button';button.type='button';button.className='secondary-button';button.textContent='Preferences';document.querySelector('.topbar-actions').append(button);
const dialog=document.createElement('dialog');dialog.className='experience-dialog';dialog.innerHTML=`<header><h2>Appearance & notifications</h2><button type="button" data-close aria-label="Close preferences">×</button></header><label>Appearance<select id="experience-theme"><option value="system">Use device setting</option><option value="light">Light</option><option value="dark">Dark</option></select></label><p>Drag Ask Elder to move it. You can also focus it and use Alt + arrow keys.</p><button type="button" id="elder-reset">Reset Ask Elder position</button><hr><h3>Notifications on this device</h3><p>Receive alerts even when the Hub tab is closed. Your existing notification categories and muted conversations still apply.</p><button type="button" id="push-enable">Enable notifications</button><button type="button" id="push-disable">Disable on this device</button><form id="push-hours"><label>Quiet hours start<input name="start" type="time"></label><label>Quiet hours end<input name="end" type="time"></label><label>Time zone<input name="zone" value="Africa/Blantyre" required></label><p>Leave both times empty for alerts at any time. Quiet-hour alerts remain in the notification centre.</p><button type="submit">Save quiet hours</button></form><p id="experience-status" role="status"></p>`;document.body.append(dialog);
dialog.querySelector('[data-close]').onclick=()=>dialog.close();const status=s=>$('experience-status').textContent=s;
function apply(theme){try{localStorage.setItem('cage-appearance',theme);}catch{}document.documentElement.dataset.cageTheme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.querySelector('.chat-workspace')?.setAttribute('data-messenger-theme',document.documentElement.dataset.cageTheme);}
$('experience-theme').onchange=e=>apply(e.target.value);matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{let t='system';try{t=localStorage.getItem('cage-appearance')||t;}catch{}if(t==='system')apply(t);});
button.onclick=async()=>{dialog.showModal();try{$('experience-theme').value=localStorage.getItem('cage-appearance')||'system';prefs=await api().hubCall('hub_push_settings');const reg=await navigator.serviceWorker?.getRegistration('/');pushEnabled=!!prefs.push_enabled&&!!(await reg?.pushManager.getSubscription());$('push-hours').elements.start.value=prefs.quiet_start?.slice(0,5)||'';$('push-hours').elements.end.value=prefs.quiet_end?.slice(0,5)||'';$('push-hours').elements.zone.value=prefs.timezone||'Africa/Blantyre';status(pushEnabled?'Push is enabled for your account. Each device needs its own permission.':'Push is not enabled yet.');}catch(e){status(e.message);}};
const bytes=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
async function registration(){if(!isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('This browser does not support push here. On iPhone or iPad, add CAGE to your Home Screen and open it there.');await navigator.serviceWorker.register('/hub-push-sw.js',{scope:'/'});return navigator.serviceWorker.ready;}
$('push-enable').onclick=async()=>{const b=$('push-enable');b.disabled=true;try{if(!window.Notification)throw Error('Add CAGE to your Home Screen first, or use a supported browser.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications are blocked. Allow them in your browser/site settings, then try again.');const config=await api().pushConfig();if(!config.publicKey)throw Error('Push has not been configured on the server yet.');const reg=await registration();let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes(config.publicKey)});await api().hubCall('hub_push_save',{subscription:sub.toJSON()});pushEnabled=true;reg.active?.postMessage({type:'account',user:api().currentProfile().id});status('Notifications enabled on this device.');}catch(e){status(e.message);}finally{b.disabled=false;}};
$('push-disable').onclick=async()=>{try{const reg=await navigator.serviceWorker?.getRegistration('/');const sub=await reg?.pushManager.getSubscription();if(sub){await api().hubCall('hub_push_remove',{endpoint_value:sub.endpoint});await sub.unsubscribe();}pushEnabled=false;status('Notifications disabled on this device.');}catch(e){status(e.message);}};
$('push-hours').onsubmit=async e=>{e.preventDefault();try{const f=e.target,s=f.elements.start.value,t=f.elements.end.value;if(Boolean(s)!==Boolean(t)||s&&s===t)throw Error('Choose different start and end times, or clear both.');new Intl.DateTimeFormat('en',{timeZone:f.elements.zone.value});await api().hubCall('hub_push_preferences',{start_value:s||null,end_value:t||null,zone_value:f.elements.zone.value});status('Quiet hours saved.');}catch(e){status(e.message);}};
// Store placement per person; pointer capture supports mouse and touch. Click after a drag is suppressed.
let installed=false;
function draggable(){const el=$('elder-launcher');if(!el||installed)return;installed=true;let drag=null,suppress=false;const key=()=>`cage-elder-position:${api()?.currentProfile?.()?.id||'local'}`;
const place=(x,y)=>{el.style.right='auto';el.style.bottom='auto';el.style.left=Math.max(8,Math.min(innerWidth-el.offsetWidth-8,x))+'px';el.style.top=Math.max(8,Math.min(innerHeight-el.offsetHeight-8,y))+'px';};
const save=()=>{try{localStorage.setItem(key(),JSON.stringify({x:parseFloat(el.style.left)/innerWidth,y:parseFloat(el.style.top)/innerHeight}));}catch{}};
const restore=()=>{try{const p=JSON.parse(localStorage.getItem(key())||'null');if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y))place(p.x*innerWidth,p.y*innerHeight);else{el.style.left=el.style.top=el.style.right=el.style.bottom='';}}catch{}};
el.title='Ask Elder — drag to move; Alt + arrow keys to reposition';el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=el.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false};el.setPointerCapture(e.pointerId);});
el.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>6)drag.moved=true;if(drag.moved){el.classList.add('is-dragging');place(drag.left+dx,drag.top+dy);}});
const end=e=>{if(!drag||drag.id!==e.pointerId)return;suppress=drag.moved;if(drag.moved)save();drag=null;el.classList.remove('is-dragging');setTimeout(()=>suppress=false,0);};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopImmediatePropagation();}},true);
el.addEventListener('keydown',e=>{if(!e.altKey||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const r=el.getBoundingClientRect();place(r.left+(e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0),r.top+(e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0));save();});window.addEventListener('resize',restore);window.addEventListener('cage:session-ready',restore);$('elder-reset').onclick=()=>{try{localStorage.removeItem(key());}catch{}restore();status('Ask Elder position reset.');};restore();}
const observer=new MutationObserver(()=>{draggable();if(installed)observer.disconnect();});observer.observe(document.body,{childList:true});draggable();
window.addEventListener('cage:unread-updated',()=>{const total=window.CAGE_PERSONAL?.chatUnreadTotal?.();if(Number.isFinite(total))$('chat-nav-count').textContent=total;document.querySelectorAll('[data-chat-thread]').forEach(el=>{const count=window.CAGE_PERSONAL?.chatUnread?.(el.dataset.chatThread)||0;el.classList.toggle('has-unread',count>0);let badge=el.querySelector('.unread-count');if(!count)badge?.remove();else if(badge)badge.textContent=count;else{badge=document.createElement('span');badge.className='unread-count';badge.textContent=count;el.querySelector('.chat-channel-status')?.append(badge);}});const tab=document.querySelector('[data-chat-filter="unread"]');if(tab)tab.textContent=total?`Unread ${total}`:'Unread';});
async function openNotice(id){try{const n=await api().hubCall('hub_push_read',{notice_id:id});if(!n)return;setView(n.target_view);if(n.target_view==='chat')selectChatThread(n.target_id);else if(n.target_view==='tasks')openTask(n.target_id);else if(n.target_view==='projects')openProject(n.target_id);else if(n.target_view==='requests')openRequest(n.target_id);else if(['calendar','notices'].includes(n.target_view))await window.CAGE_COLLAB?.open(n.target_view,n.target_id);await window.CAGE_PERSONAL?.refresh?.();}catch(e){showToast(e.message);}}
navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='open-notification')openNotice(e.data.id);});
window.addEventListener('cage:session-ready',async()=>{try{const reg=await navigator.serviceWorker?.getRegistration('/');reg?.active?.postMessage({type:'account',user:api().currentProfile().id});const sub=await reg?.pushManager.getSubscription();if(sub&&Notification.permission==='granted')await api().hubCall('hub_push_save',{subscription:sub.toJSON()});prefs=await api().hubCall('hub_push_settings');pushEnabled=!!prefs.push_enabled&&!!sub;const u=new URL(location.href),id=u.searchParams.get('notification');if(id){u.searchParams.delete('notification');history.replaceState(null,'',u);await openNotice(id);}}catch{}});
$('sign-out-button')?.addEventListener('click',()=>{pushEnabled=false;navigator.serviceWorker?.getRegistration('/').then(async r=>{r?.active?.postMessage({type:'account',user:null});const sub=await r?.pushManager.getSubscription();if(sub){api().hubCall('hub_push_remove',{endpoint_value:sub.endpoint}).catch(()=>{});await sub.unsubscribe();}}).catch(()=>{});},true);
})();
